//! `levels/ffa_circuit.lvl` (generated by `scripts/gen_circuit_level.py`): the Circuit-Breaker Arena Phase 1 blockout
//! plus its zone/mover layer. Pinned: the 100 x 100 m sealed deck over void, the 30 x 30 m split-level nexus and its
//! four pit ramps, the four 10 m data lanes with 8 m wall-run faces, the ten outer-ring spawns and six data-cube pickups,
//! the upper ring and its 2 m gaps, static access to it, the box budget and the destructible gameplay share. Also pinned:
//! eight solid piston movers (four 3 s pairs), four `speed_lane` zones, the `core_vent` zone, their exact tuning and
//! fingerprint, and that no feature volume blocks a spawn, pickup or main route. No `hazard` lines ship yet.

use std::collections::{BTreeMap, HashSet, VecDeque};
use std::f32::consts::{PI, TAU};
use std::time::Duration;

use shinobi_proto::intent::{ClientPacket, PlayerIntent, ViewState, PITCH_LEVEL};
use shinobi_proto::quant::{dq_yaw, q_yaw};
use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{parse_level_file, unwalkable_obstacles, LevelBox, LevelFile, MoveAxis, MoverDef, ZoneDef};
use shinobi_sim::power::PowerKind;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::blocked;
use shinobi_sim::tick::Server;

const HALF: f32 = 50.0;
const PIT: f32 = 8.0;
const PIT_FLOOR: f32 = -6.0;
const NEXUS: f32 = 15.0;
const UPPER: f32 = 9.0;
const WALL: f32 = 41.0;
const LANE_IN: f32 = 13.0;
const LANE_OUT: f32 = 41.0;
const LANE_HALF: f32 = 5.0;
const WALL_TOP: f32 = 8.0;

fn level_text() -> String {
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_circuit.lvl");
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn load() -> LevelFile {
    parse_level_file(&level_text()).unwrap_or_else(|e| panic!("ffa_circuit.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld {
        bodies: RigidBodySet::new(),
        colliders: ColliderSet::new(),
        islands: IslandManager::new(),
        queries: QueryPipeline::new(),
    };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

fn surface_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn top_at(l: &LevelFile, x: f32, z: f32) -> Option<f32> {
    l.level
        .boxes
        .iter()
        .filter_map(|b| surface_at(b, x, z))
        .fold(None, |m: Option<f32>, h| Some(m.map_or(h, |m| m.max(h))))
}

fn solid(l: &LevelFile, p: [f32; 3]) -> bool {
    l.level.boxes.iter().any(|b| inside(b, p))
}

fn d2(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

fn d3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

fn box_dist_xz(b: &LevelBox, p: [f32; 3]) -> f32 {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, _v) = (dx * c + dy * s, -dx * s + dy * c);
    let ex = (u.abs() - b.half[0]).max(0.0);
    let ez = (p[2] - b.center[2]).abs() - b.half[2];
    (ex * ex + ez.max(0.0) * ez.max(0.0)).sqrt()
}

/// `true` for a box under a `# --- structural:` section header. The generator is the source of that classification;
/// gameplay sections are the breakable data racks plus the permanent plaza hard cover.
fn structural_sections(text: &str) -> Vec<bool> {
    let mut structural = true;
    let mut out = Vec::new();
    for raw in text.lines() {
        if raw.starts_with("# ---") {
            structural = raw.starts_with("# --- structural:");
            continue;
        }
        let line = raw.split('#').next().unwrap().trim_start();
        if line.starts_with("box ") || line.starts_with("dbox ") {
            out.push(structural);
        }
    }
    out
}

fn is_ring_segment(b: &LevelBox) -> bool {
    let top = b.center[1] + b.half[1];
    let long = b.half[0].max(b.half[2]);
    (top - UPPER).abs() < 0.01 && (b.half[1] - 0.3).abs() < 0.01 && long >= 5.9
}

fn is_lane_wall(b: &LevelBox) -> bool {
    (b.center[1] + b.half[1] - WALL_TOP).abs() < 0.01 && (b.half[1] - 4.0).abs() < 0.01
}

fn first_hit(w: &PhysicsWorld, from: [f32; 3], to: [f32; 3]) -> Option<f32> {
    let d = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
    let len = (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt();
    if len < 1e-3 {
        return None;
    }
    let ray = Ray::new(
        Point::new(from[0], from[1], from[2]),
        vector![d[0] / len, d[1] / len, d[2] / len],
    );
    w.queries
        .cast_ray(
            &w.bodies,
            &w.colliders,
            &ray,
            len,
            true,
            QueryFilter::default(),
        )
        .map(|(_, t)| t)
}

fn near_box(b: &LevelBox, p: [f32; 3], pad: f32) -> bool {
    inside(
        &LevelBox {
            half: [b.half[0] + pad, b.half[1] + pad, b.half[2] + pad],
            ..*b
        },
        p,
    )
}

fn zone_aabb(z: &ZoneDef) -> ([f32; 3], [f32; 3]) {
    (z.center, z.half)
}

fn mover_swept(m: &MoverDef) -> ([f32; 3], [f32; 3]) {
    let mut lo = [m.center[0] - m.half[0], m.center[1] - m.half[1], m.center[2] - m.half[2]];
    let mut hi = [m.center[0] + m.half[0], m.center[1] + m.half[1], m.center[2] + m.half[2]];
    let a = m.axis.index();
    lo[a] = lo[a].min(m.center[a] + m.distance - m.half[a]);
    hi[a] = hi[a].max(m.center[a] + m.distance + m.half[a]);
    (lo, hi)
}

fn in_aabb(lo: [f32; 3], hi: [f32; 3], p: [f32; 3], pad: f32) -> bool {
    (0..3).all(|i| p[i] >= lo[i] - pad && p[i] <= hi[i] + pad)
}

fn aabbs_overlap(a: ([f32; 3], [f32; 3]), b: ([f32; 3], [f32; 3])) -> bool {
    (0..3).all(|i| a.0[i] < b.1[i] - 1e-3 && b.0[i] < a.1[i] - 1e-3)
}

fn angle_diff(to: f32, from: f32) -> f32 {
    (to - from + PI).rem_euclid(TAU) - PI
}

/// Points on the main traversal routes a piston must never sweep through: lane centrelines and mouths, pit-ramp
/// centrelines, the nexus cardinal crossing, and the upper ring.
fn main_route_points() -> Vec<[f32; 3]> {
    let mut out = Vec::new();
    for t in LANE_IN as i32..=LANE_OUT as i32 {
        let f = t as f32;
        for (x, z) in [(f, 0.0), (-f, 0.0), (0.0, f), (0.0, -f)] {
            out.push([x, 1.0, z]);
            out.push([x, 2.5, z]);
        }
    }
    for t in [LANE_IN, 14.0, 15.0] {
        for u in -5i32..=5 {
            let u = u as f32;
            for (x, z) in [(t, u), (-t, u), (u, t), (u, -t)] {
                out.push([x, 1.0, z]);
                out.push([x, 2.5, z]);
            }
        }
    }
    for zc in [-6.5f32, -5.0, 5.0, 6.5] {
        for x in -8i32..=8 {
            out.push([x as f32, 1.0, zc]);
            out.push([x as f32, 2.5, zc]);
        }
    }
    for t in -15i32..=15 {
        let f = t as f32;
        for (x, z) in [(f, 0.0), (0.0, f)] {
            out.push([x, 1.0, z]);
            out.push([x, 2.5, z]);
        }
    }
    for (x, z) in [(0.0, -8.5), (0.0, 8.5), (8.5, 0.0), (-8.5, 0.0)] {
        out.push([x, UPPER - 0.3, z]);
    }
    out
}

#[test]
fn counts_budget_bricks_and_destructible_gameplay_share() {
    let l = load();
    let text = level_text();
    let sections = structural_sections(&text);
    assert_eq!(
        sections.len(),
        l.level.boxes.len(),
        "every box line has a section header"
    );

    assert!(
        (60..=1800).contains(&l.level.boxes.len()),
        "{} boxes (budget 1800)",
        l.level.boxes.len()
    );
    assert_eq!(l.level.spawns.len(), 10, "ten outer-ring spawns");
    assert_eq!(l.pickups.len(), 6, "six data cubes");
    assert!(
        l.pickups.iter().all(|p| p.kind == PowerKind::None),
        "no weapon pedestals"
    );
    assert_eq!(
        l.pickups.iter().filter(|p| p.respawn_secs == 25.0).count(),
        4,
        "four lane-mouth cubes at 25 s"
    );
    assert_eq!(
        l.pickups.iter().filter(|p| p.respawn_secs == 30.0).count(),
        2,
        "two upper-ring cubes at 30 s"
    );
    assert_eq!(l.level.floor_half(), Some(HALF), "one 100 x 100 m deck");

    let (mut total, mut destructible) = (0.0f32, 0.0f32);
    let (mut gameplay_boxes, mut gameplay_destructible) = (0usize, 0usize);
    for (b, structural) in l.level.boxes.iter().zip(&sections) {
        let vol = 8.0 * b.half[0] * b.half[1] * b.half[2];
        if *structural {
            assert_eq!(b.hp, 0.0, "structural box must be permanent: {b:?}");
            continue;
        }
        gameplay_boxes += 1;
        let min_side = 2.0 * b.half[0].min(b.half[1]).min(b.half[2]);
        let max_side = 2.0 * b.half[0].max(b.half[1]).max(b.half[2]);
        assert!(
            min_side >= 1.99,
            "gameplay brick {b:?} is only {min_side:.2} m on its short side"
        );
        assert!(
            max_side <= 6.01,
            "gameplay brick {b:?} is {max_side:.2} m long"
        );
        total += vol;
        if b.hp > 0.0 {
            gameplay_destructible += 1;
            destructible += vol;
        }
    }
    assert!(gameplay_boxes >= 24, "only {gameplay_boxes} gameplay boxes");
    assert!(
        gameplay_destructible >= 16,
        "only {gameplay_destructible} destructible data-rack bricks"
    );
    assert!(
        destructible / total >= 0.70,
        "only {:.0}% of gameplay volume is destructible",
        100.0 * destructible / total
    );

    let unwalkable = unwalkable_obstacles(&l.level, Cfg::default().step_height);
    assert!(
        unwalkable.is_empty(),
        "jump-only lips at {unwalkable:?}: {:?}",
        unwalkable
            .iter()
            .map(|i| l.level.boxes[*i])
            .collect::<Vec<_>>()
    );
    assert_eq!(
        world(&l).colliders.len(),
        l.level.boxes.len(),
        "every box becomes one collider"
    );
}

#[test]
fn footprint_is_100_by_100_with_a_sealed_perimeter_and_void_beyond() {
    let l = load();
    let far = l
        .level
        .boxes
        .iter()
        .map(|b| b.center[0].abs() + b.half[0])
        .chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2]))
        .fold(0.0f32, f32::max);
    assert!(far <= HALF + 0.01, "geometry reaches {far} m sideways");
    let top = l
        .level
        .boxes
        .iter()
        .map(|b| b.center[1] + b.half[1])
        .fold(0.0f32, f32::max);
    assert!(top <= 30.0, "tallest geometry is {top} m");

    // Deck at y = 0 everywhere outside the 16 x 16 m pit hole, and the pit floor six metres below it.
    let mut x: f32 = -49.0;
    while x <= 49.0 {
        let mut z: f32 = -49.0;
        while z <= 49.0 {
            if x.abs() < PIT - 0.25 && z.abs() < PIT - 0.25 {
                let fan = x.abs() < 1.5 && z.abs() < 1.5;
                assert!(
                    fan || !solid(&l, [x, -0.25, z]),
                    "deck fills the pit at ({x}, {z})"
                );
            } else {
                assert!(solid(&l, [x, -0.25, z]), "deck gap at ({x}, {z})");
            }
            if x.abs() < PIT - 0.25 && z.abs() < PIT - 0.25 {
                assert!(
                    solid(&l, [x, PIT_FLOOR - 0.25, z]),
                    "pit floor gap at ({x}, {z})"
                );
            }
            z += 2.0;
        }
        x += 2.0;
    }

    // Four perimeter walls block every body-height crossing; nothing stands outside them.
    for t in (-49..=49).step_by(1) {
        let p = t as f32 + 0.5;
        assert!(
            solid(&l, [HALF - 0.5, 1.0, p]) && solid(&l, [-HALF + 0.5, 1.0, p]),
            "east/west perimeter gap at z {p}"
        );
        assert!(
            solid(&l, [p, 1.0, HALF - 0.5]) && solid(&l, [p, 1.0, -HALF + 0.5]),
            "north/south perimeter gap at x {p}"
        );
    }
    for p in [
        [HALF + 1.0, 0.5, 0.0],
        [-HALF - 1.0, 0.5, 0.0],
        [0.0, 0.5, HALF + 1.0],
        [0.0, 0.5, -HALF - 1.0],
    ] {
        assert!(!solid(&l, p), "geometry outside the perimeter at {p:?}");
    }
}

#[test]
fn spawns_are_supported_clear_and_each_has_two_ring_exits() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        assert!(
            (s[1] - 0.81).abs() < 0.01,
            "spawn {s:?} is not a deck spawn"
        );
        let radial = s[0].abs().max(s[2].abs());
        assert!(
            (44.0..=47.0).contains(&radial),
            "spawn {s:?} is not on the outer ring"
        );
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [
                (0.0, 0.0),
                (cfg.radius, 0.0),
                (-cfg.radius, 0.0),
                (0.0, cfg.radius),
                (0.0, -cfg.radius),
            ] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(
                    !solid(&l, p),
                    "spawn {s:?}: capsule point {p:?} is inside geometry"
                );
            }
        }
        let support = l.level.boxes.iter().find(|b| {
            surface_at(b, s[0], s[2]).map_or(false, |h| (h - (s[1] - reach)).abs() < 0.1)
        });
        let support = support.unwrap_or_else(|| panic!("spawn {s:?} floats"));
        assert_eq!(support.hp, 0.0, "spawn {s:?} stands on a breaking box");
        for b in &l.level.boxes {
            if std::ptr::eq(b, support) {
                continue;
            }
            let spans_body =
                b.center[1] + b.half[1] > s[1] - reach && b.center[1] - b.half[1] < s[1] + 2.0;
            if spans_body {
                assert!(
                    box_dist_xz(b, *s) >= 3.4,
                    "spawn {s:?} is only {:.2} m from {b:?}",
                    box_dist_xz(b, *s)
                );
            }
        }
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n)
        .map(|i| {
            (0..n)
                .filter(|j| *j != i)
                .map(|j| d2(l.level.spawns[i], l.level.spawns[j]))
                .fold(f32::MAX, f32::min)
        })
        .collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    let max = nearest.iter().copied().fold(0.0f32, f32::max);
    assert!(min >= 15.0, "two spawns only {min:.1} m apart");
    assert!(
        max <= 36.0,
        "a spawn is {max:.1} m from its nearest neighbour"
    );

    assert!(
        ring_has_two_exits(&l),
        "a spawn cannot reach two lane exits around the outer ring"
    );
}

/// Flood the 7 m outer-ring corridor on a 1 m grid (body and head clear, deck underfoot). The loop must be one component
/// and every spawn must touch it; at least two of the four lane-mouth gaps must border the component.
fn ring_has_two_exits(l: &LevelFile) -> bool {
    let n = 100i32;
    let coord = |i: i32| -49.5 + i as f32;
    let in_band = |p: [f32; 3]| {
        let r = p[0].abs().max(p[2].abs());
        (42.5..=48.5).contains(&r)
    };
    let walkable = |p: [f32; 3]| {
        !solid(l, [p[0], 1.0, p[2]])
            && !solid(l, [p[0], 2.6, p[2]])
            && top_at(l, p[0], p[2]).map_or(false, |h| h.abs() < 0.05)
    };
    let mut cells: HashSet<(i32, i32)> = HashSet::new();
    for iz in 0..n {
        for ix in 0..n {
            let p = [coord(ix), 0.81, coord(iz)];
            if in_band(p) && walkable(p) {
                cells.insert((ix, iz));
            }
        }
    }
    let cell_of = |p: [f32; 3]| {
        (
            ((p[0] + 49.5) / 1.0).round() as i32,
            ((p[2] + 49.5) / 1.0).round() as i32,
        )
    };
    let start = cell_of(l.level.spawns[0]);
    assert!(
        cells.contains(&start),
        "the first spawn is not on the ring grid"
    );
    let mut seen = HashSet::from([start]);
    let mut q = VecDeque::from([start]);
    while let Some((x, z)) = q.pop_front() {
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let c = (x + dx, z + dz);
            if cells.contains(&c) && seen.insert(c) {
                q.push_back(c);
            }
        }
    }
    assert_eq!(
        seen.len(),
        cells.len(),
        "the outer ring is not one walkable loop"
    );
    for s in &l.level.spawns {
        assert!(
            seen.contains(&cell_of(*s)),
            "spawn {s:?} is not on the reachable ring"
        );
    }
    // One cell just outside each 10 m lane gap. All four border the single ring component; any spawn can use two ways round.
    let mouths = [
        cell_of([42.5, 0.81, 0.5]),
        cell_of([-42.5, 0.81, 0.5]),
        cell_of([0.5, 0.81, 42.5]),
        cell_of([0.5, 0.81, -42.5]),
    ];
    mouths.iter().all(|m| seen.contains(m))
}

#[test]
fn four_ten_metre_lanes_have_eight_metre_wall_run_faces_and_open_mouths() {
    let l = load();
    let walls: Vec<&LevelBox> = l.level.boxes.iter().filter(|b| is_lane_wall(b)).collect();
    assert_eq!(walls.len(), 8, "four lanes x two wall-run faces");
    for b in &walls {
        let long = b.half[0].max(b.half[2]);
        assert!(
            (long - 14.0).abs() < 0.01,
            "lane wall {b:?} is not 28 m long"
        );
        assert_eq!(b.hp, 0.0, "wall-run faces are permanent");
    }

    for axis in 0..2 {
        for side in [-1.0f32, 1.0] {
            let mut t = LANE_IN + 1.0;
            while t <= LANE_OUT - 1.0 {
                let p = if axis == 0 {
                    [side * t, 0.81, 0.0]
                } else {
                    [0.0, 0.81, side * t]
                };
                assert!(!solid(&l, p), "lane {axis}/{side} is blocked at {p:?}");
                assert!(
                    !solid(&l, [p[0], 2.5, p[2]]),
                    "lane {axis}/{side} has no headroom at {p:?}"
                );
                assert!(
                    top_at(&l, p[0], p[2]).map_or(false, |h| h.abs() < 0.05),
                    "lane {axis}/{side} has no deck at {p:?}"
                );
                t += 1.0;
            }
            // inner (nexus) and outer (spawn-ring) mouths are open across the full 10 m lane width
            for q in 0..2 {
                let u = -LANE_HALF + 1.0 + 8.0 * q as f32;
                let inside_mouth = if axis == 0 {
                    [side * (NEXUS - 1.0), 4.0, u]
                } else {
                    [u, 4.0, side * (NEXUS - 1.0)]
                };
                let outside_mouth = if axis == 0 {
                    [side * (WALL + 0.5), 4.0, u]
                } else {
                    [u, 4.0, side * (WALL + 0.5)]
                };
                assert!(
                    !solid(&l, inside_mouth),
                    "lane {axis}/{side} nexus mouth is blocked at {inside_mouth:?}"
                );
                assert!(
                    !solid(&l, outside_mouth),
                    "lane {axis}/{side} spawn-ring mouth is blocked at {outside_mouth:?}"
                );
            }
        }
    }
    // from the lane mouth into the nexus floor and from the lane end into the spawn ring
    for p in [
        [NEXUS - 1.0, 0.5, 0.0],
        [WALL + 1.0, 0.5, 0.0],
        [0.0, 0.5, NEXUS - 1.0],
        [0.0, 0.5, WALL + 1.0],
    ] {
        assert!(
            top_at(&l, p[0], p[2]).map_or(false, |h| h.abs() < 0.05),
            "lane mouth {p:?} has no deck"
        );
    }
}

#[test]
fn the_four_pit_ramps_join_the_lower_pit_to_the_ground_ring() {
    let l = load();
    assert!(
        l.level
            .boxes
            .iter()
            .any(|b| surface_at(b, 6.0, 0.0).map_or(false, |h| (h - PIT_FLOOR).abs() < 0.01)),
        "no lower pit floor"
    );
    let ramps: Vec<&LevelBox> = l.level.boxes.iter().filter(|b| b.rot_z != 0.0).collect();
    assert_eq!(ramps.len(), 4, "four pit ramps");
    for b in &ramps {
        assert!(
            b.rot_z.abs() <= 30f32.to_radians() + 1e-3,
            "ramp {b:?} is steeper than 30 degrees"
        );
        let mut samples = Vec::new();
        let mut x = -8.0;
        while x <= 8.0 {
            if let Some(h) = surface_at(b, x, b.center[2]) {
                samples.push((x, h));
            }
            x += 0.25;
        }
        assert!(
            samples.len() > 20,
            "ramp {b:?} has too little walkable surface"
        );
        let (x0, h0) = samples[0];
        let (x1, h1) = *samples.last().unwrap();
        assert!(
            (h0 - PIT_FLOOR).abs() < 0.15 || (h1 - PIT_FLOOR).abs() < 0.15,
            "ramp {b:?} does not start at the pit floor"
        );
        assert!(
            h0.abs() < 0.15 || h1.abs() < 0.15,
            "ramp {b:?} does not reach the ground ring"
        );
        let slope = (h1 - h0) / (x1 - x0);
        for w in samples.windows(2) {
            let s = (w[1].1 - w[0].1) / (w[1].0 - w[0].0);
            assert!((s - slope).abs() < 1e-3, "ramp {b:?} is not straight");
            assert!(s.abs() <= 0.6, "ramp {b:?} climbs too steeply");
        }
    }

    // A 1 m surface flood from the pit floor reaches both the east and south ground ring (the ramps are the only way up).
    let cells = low_surfaces(&l);
    let node = |x: f32, z: f32, y: f32| {
        (
            x.floor() as i32,
            z.floor() as i32,
            (y * 100.0).round() as i32,
        )
    };
    let start = node(6.5, 0.5, PIT_FLOOR);
    assert!(
        cells.contains_key(&(start.0, start.1)),
        "pit floor start cell is not walkable"
    );
    let mut seen = HashSet::from([start]);
    let mut q = VecDeque::from([start]);
    while let Some((x, z, hy)) = q.pop_front() {
        let y = hy as f32 / 100.0;
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            for &ny in cells.get(&(x + dx, z + dz)).into_iter().flatten() {
                if (ny - y).abs() <= 0.55 {
                    let n = (x + dx, z + dz, (ny * 100.0).round() as i32);
                    if seen.insert(n) {
                        q.push_back(n);
                    }
                }
            }
        }
    }
    assert!(
        seen.contains(&node(12.5, 0.5, 0.0)),
        "the east ground ring cannot be reached from the pit"
    );
    assert!(
        seen.contains(&node(0.5, 12.5, 0.0)),
        "the south ground ring cannot be reached from the pit"
    );
}

/// Low-level walkable surfaces (pit floor, ramps and the ground deck) on a 1 m grid, with 1.8 m of headroom.
fn low_surfaces(l: &LevelFile) -> std::collections::HashMap<(i32, i32), Vec<f32>> {
    let mut out = std::collections::HashMap::new();
    for x in -15i32..15 {
        for z in -15i32..15 {
            let (px, pz) = (x as f32 + 0.5, z as f32 + 0.5);
            let mut hs: Vec<f32> = Vec::new();
            for b in &l.level.boxes {
                if let Some(h) = surface_at(b, px, pz) {
                    if !(-6.2..=1.0).contains(&h) {
                        continue;
                    }
                    let blocked = l
                        .level
                        .boxes
                        .iter()
                        .any(|o| inside(o, [px, h + 0.9, pz]) || inside(o, [px, h + 1.8, pz]));
                    if !blocked && !hs.iter().any(|g| (g - h).abs() < 0.05) {
                        hs.push(h);
                    }
                }
            }
            if !hs.is_empty() {
                out.insert((x, z), hs);
            }
        }
    }
    out
}

#[test]
fn upper_ring_has_four_2_m_gap_segments_and_static_access() {
    let l = load();
    let ring: Vec<&LevelBox> = l
        .level
        .boxes
        .iter()
        .filter(|b| is_ring_segment(b))
        .collect();
    assert_eq!(ring.len(), 4, "four upper-ring segments");
    for b in &ring {
        assert_eq!(b.hp, 0.0, "upper ring is permanent");
        assert!(
            (b.half[0].min(b.half[2]) - 1.5).abs() < 0.01,
            "upper-ring segment {b:?} is not 3 m wide"
        );
    }
    // The four segments sit on the sides of a 20 x 20 m square. Adjacent ends are 1 m apart on each axis, i.e. a 2 m
    // walkable gap round the corner (there is no deck in the corner notches).
    let side = |b: &LevelBox| {
        if (b.center[2] + 8.5).abs() < 0.01 {
            0
        } else if (b.center[0] - 8.5).abs() < 0.01 {
            1
        } else if (b.center[2] - 8.5).abs() < 0.01 {
            2
        } else {
            3
        }
    };
    let mut by_side = [None; 4];
    for b in &ring {
        by_side[side(b)] = Some(*b);
    }
    let x0 = |b: &LevelBox| b.center[0] - b.half[0];
    let x1 = |b: &LevelBox| b.center[0] + b.half[0];
    let z0 = |b: &LevelBox| b.center[2] - b.half[2];
    let z1 = |b: &LevelBox| b.center[2] + b.half[2];
    for a in 0..4 {
        let p = by_side[a].unwrap();
        let q = by_side[(a + 1) % 4].unwrap();
        let gap_x = (x0(&p) - x1(&q)).max(x0(&q) - x1(&p)).max(0.0);
        let gap_z = (z0(&p) - z1(&q)).max(z0(&q) - z1(&p)).max(0.0);
        assert!(
            (gap_x + gap_z - 2.0).abs() < 0.01,
            "upper-ring gap between {p:?} and {q:?} is {:.2} m",
            gap_x + gap_z
        );
    }
    // braces tie every segment to the fan column
    let braces = l
        .level
        .boxes
        .iter()
        .filter(|b| {
            (b.center[1] + b.half[1] - UPPER).abs() < 0.01
                && (b.half[1] - 0.3).abs() < 0.01
                && b.half[0].max(b.half[2]) < 3.0
        })
        .count();
    assert_eq!(braces, 4, "four fan braces");

    // Static access: every segment is a clear grapple target from the ground ring / lane floor.
    let w = world(&l);
    let mut ground = Vec::new();
    for x in -14i32..14 {
        for z in -14i32..14 {
            let p = [x as f32 + 0.5, 1.4, z as f32 + 0.5];
            if !solid(&l, p) && top_at(&l, p[0], p[2]).map_or(false, |h| h.abs() < 0.05) {
                ground.push(p);
            }
        }
    }
    for b in &ring {
        let targets = [
            [b.center[0], b.center[1] - b.half[1] + 0.05, b.center[2]],
            [
                b.center[0] + b.half[0] * 0.8,
                b.center[1] - b.half[1] + 0.05,
                b.center[2],
            ],
            [
                b.center[0] - b.half[0] * 0.8,
                b.center[1] - b.half[1] + 0.05,
                b.center[2],
            ],
            [
                b.center[0],
                b.center[1] - b.half[1] + 0.05,
                b.center[2] + b.half[2] * 0.8,
            ],
            [
                b.center[0],
                b.center[1] - b.half[1] + 0.05,
                b.center[2] - b.half[2] * 0.8,
            ],
        ];
        let mut reachable = false;
        'search: for from in &ground {
            for to in targets {
                if let Some(t) = first_hit(&w, *from, to) {
                    let len = d3(*from, to);
                    if t >= len - 0.2 {
                        let hit = [
                            from[0] + (to[0] - from[0]) * t / len,
                            from[1] + (to[1] - from[1]) * t / len,
                            from[2] + (to[2] - from[2]) * t / len,
                        ];
                        if near_box(b, hit, 0.5) {
                            reachable = true;
                            break 'search;
                        }
                    }
                }
            }
        }
        assert!(
            reachable,
            "upper-ring segment {b:?} has no clear grapple line from the ground"
        );
    }

    // Wall-run + jump access too: every lane wall top is within a jump of a ring segment (3 m horizontal, 1 m up).
    let hop = Cfg::default().max_hop_rise(0.3);
    for b in l.level.boxes.iter().filter(|b| is_lane_wall(b)) {
        let near = ring.iter().any(|r| {
            let dx = ((b.center[0] - b.half[0]) - (r.center[0] + r.half[0]))
                .max((r.center[0] - r.half[0]) - (b.center[0] + b.half[0]))
                .max(0.0);
            let dz = ((b.center[2] - b.half[2]) - (r.center[2] + r.half[2]))
                .max((r.center[2] - r.half[2]) - (b.center[2] + b.half[2]))
                .max(0.0);
            (dx * dx + dz * dz).sqrt() <= 4.0 && UPPER - WALL_TOP <= hop
        });
        assert!(
            near,
            "lane wall {b:?} has no wall-run + jump route to the upper ring"
        );
    }
}

#[test]
fn six_data_cubes_are_supported_clear_and_on_permanent_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!solid(&l, p.pos), "pickup {:?} is inside geometry", p.pos);
        let support = l.level.boxes.iter().find(|b| {
            surface_at(b, p.pos[0], p.pos[2]).map_or(false, |h| (p.pos[1] - h - 1.0).abs() < 0.3)
        });
        let support =
            support.unwrap_or_else(|| panic!("pickup {:?} is not 1 m above a surface", p.pos));
        assert_eq!(
            support.hp, 0.0,
            "pickup {:?} is above a breaking box",
            p.pos
        );
        for b in &l.level.boxes {
            if std::ptr::eq(b, support) {
                continue;
            }
            let spans_body = b.center[1] + b.half[1] > p.pos[1] - 0.5
                && b.center[1] - b.half[1] < p.pos[1] + 1.5;
            if spans_body {
                assert!(
                    box_dist_xz(b, p.pos) >= 1.0,
                    "pickup {:?} is too close to {b:?}",
                    p.pos
                );
            }
        }
        // no low ceiling over a cube
        for dy in [1.0, 2.5, 3.5] {
            assert!(
                !solid(&l, [p.pos[0], p.pos[1] + dy, p.pos[2]]),
                "pickup {:?} has a low ceiling",
                p.pos
            );
        }
    }
    assert_eq!(
        l.pickups.iter().filter(|p| p.pos[1] < 2.0).count(),
        4,
        "four lane-mouth cubes"
    );
    assert_eq!(
        l.pickups.iter().filter(|p| p.pos[1] > 9.0).count(),
        2,
        "two upper-ring cubes"
    );
}

#[test]
fn spawns_have_no_line_of_sight_to_the_core_vent() {
    let l = load();
    let w = world(&l);
    let vent = [
        [4.0, -2.0, 0.0],
        [-4.0, -2.0, 0.0],
        [0.0, -2.0, 4.0],
        [0.0, -2.0, -4.0],
        [2.8, -1.2, 2.8],
        [-2.8, -1.2, -2.8],
    ];
    for s in &l.level.spawns {
        let eye = [s[0], s[1] + Cfg::default().eye_above_center, s[2]];
        for v in vent {
            assert!(
                blocked(&w, eye, v),
                "spawn {s:?} can see the core vent at {v:?}"
            );
        }
    }
}

#[test]
fn vent_and_piston_volumes_are_left_clear_for_the_runtime_pass() {
    let l = load();
    // Core vent: 8 m diameter, pit floor y=-6 to top y=-1. Only the structural fan column may stand in it.
    let mut x = -4.0;
    while x <= 4.0 {
        let mut z = -4.0;
        while z <= 4.0 {
            if x * x + z * z <= 16.0 {
                for y in [-5.5f32, -3.0, -1.5] {
                    for (i, b) in l.level.boxes.iter().enumerate() {
                        if inside(b, [x, y, z]) {
                            let fan = l.level.boxes[i].half == [1.5, 10.0, 1.5];
                            assert!(fan, "vent volume is filled by box {b:?} at ({x}, {y}, {z})");
                        }
                    }
                }
            }
            z += 1.0;
        }
        x += 1.0;
    }
    // Kinetic piston sites: four clear 6 x 6 m columns on the nexus diagonals, y 0..8.
    for sx in [-1.0f32, 1.0] {
        for sz in [-1.0f32, 1.0] {
            let (cx, cz) = (sx * 11.0, sz * 11.0);
            for dx in [-2.5f32, 0.0, 2.5] {
                for dz in [-2.5f32, 0.0, 2.5] {
                    for y in [1.0f32, 4.0, 7.5] {
                        assert!(
                            !solid(&l, [cx + dx, y, cz + dz]),
                            "piston site at ({cx}, {cz}) is filled at ({}, {y}, {})",
                            cx + dx,
                            cz + dz
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn feature_layer_is_pinned_and_keeps_spawns_pickups_and_routes_clear() {
    let l = load();
    let f = &l.features;
    assert_eq!(f.movers.len(), 8, "four piston pairs");
    assert_eq!(f.zones.len(), 5, "four data lanes plus the core vent");
    assert!(f.hazards.is_empty(), "glitch traps and vent damage are not authored yet");

    assert_eq!(f.fingerprint(), 0xfa02_e5e8_9d24_5248, "pinned feature fingerprint");
    let roundtrip = parse_level_file(&l.to_text()).unwrap();
    assert_eq!(roundtrip.features, *f, "features survive the file round-trip");
    assert_eq!(roundtrip.features.fingerprint(), f.fingerprint());

    let routes = main_route_points();
    for m in &f.movers {
        assert_eq!(m.tag, "piston");
        assert!(m.solid, "a piston face must be a server collider");
        assert_eq!(m.period_ticks, 90, "90 ticks per leg = 3 s full cycle");
        assert_eq!(m.distance, 6.0);
        assert_eq!(m.center[1], 2.0);
        assert_eq!(m.half[1], 2.0, "a hammer face is 4 m tall");
        let half = match m.axis {
            MoveAxis::X => [0.5, 2.0, 1.0],
            MoveAxis::Z => [1.0, 2.0, 0.5],
            MoveAxis::Y => panic!("pistons stay on the ground plane"),
        };
        assert_eq!(m.half, half, "1 m thick, 2 m wide hammer face");
        assert_eq!(m.tuning.len(), 1);
        let phase = m.tuning["phase_ticks"];
        assert!(phase == 0.0 || phase == 90.0, "pairs alternate ends");

        let (lo, hi) = mover_swept(m);
        for i in [0, 2] {
            let near = lo[i].abs().min(hi[i].abs());
            let far = lo[i].abs().max(hi[i].abs());
            assert!(
                near >= 7.0 && far <= 15.0,
                "piston {m:?} leaves its reserved diagonal column"
            );
        }
        assert!(lo[1] >= -0.01 && hi[1] <= 8.0, "piston {m:?} leaves y 0..8");
        for s in &l.level.spawns {
            assert!(!in_aabb(lo, hi, *s, 1.0), "piston {m:?} reaches spawn {s:?}");
        }
        for p in &l.pickups {
            assert!(!in_aabb(lo, hi, p.pos, 1.0), "piston {m:?} reaches pickup {:?}", p.pos);
        }
        for p in &routes {
            assert!(!in_aabb(lo, hi, *p, 0.0), "piston {m:?} blocks a main route at {p:?}");
        }
        for b in &l.level.boxes {
            if b.rot_z != 0.0 {
                continue;
            }
            let blo = [b.center[0] - b.half[0], b.center[1] - b.half[1], b.center[2] - b.half[2]];
            let bhi = [b.center[0] + b.half[0], b.center[1] + b.half[1], b.center[2] + b.half[2]];
            assert!(
                !aabbs_overlap((lo, hi), (blo, bhi)),
                "piston {m:?} is embedded in permanent box {b:?}"
            );
        }
    }

    let mut per_quadrant: BTreeMap<(i32, i32), usize> = BTreeMap::new();
    for m in &f.movers {
        let (lo, hi) = mover_swept(m);
        let sx = ((lo[0] + hi[0]) * 0.5).signum() as i32;
        let sz = ((lo[2] + hi[2]) * 0.5).signum() as i32;
        *per_quadrant.entry((sx, sz)).or_default() += 1;
    }
    assert_eq!(per_quadrant.len(), 4, "one pair on each nexus diagonal");
    assert!(per_quadrant.values().all(|&n| n == 2));
    assert_eq!(f.movers.iter().filter(|m| m.axis == MoveAxis::X).count(), 4);
    assert_eq!(f.movers.iter().filter(|m| m.axis == MoveAxis::Z).count(), 4);
    assert_eq!(f.movers.iter().filter(|m| m.tuning["phase_ticks"] == 0.0).count(), 4);
    assert_eq!(f.movers.iter().filter(|m| m.tuning["phase_ticks"] == 90.0).count(), 4);

    for pair in f.movers.chunks(2) {
        let (a, b) = (&pair[0], &pair[1]);
        assert_eq!(a.axis, b.axis, "a pair shares its stroke axis");
        let (pa, pb) = (a.pos_at(0), b.pos_at(0));
        let ai = a.axis.index();
        let ti = if ai == 0 { 2 } else { 0 };
        assert!(
            ((pa[ai] - pb[ai]).abs() - 6.0).abs() < 1e-4,
            "a pair starts at opposite ends of the stroke"
        );
        assert!(
            ((pa[ti] - pb[ti]).abs() - 3.0).abs() < 1e-4,
            "a pair sits on two parallel tracks"
        );
    }
    for i in 0..f.movers.len() {
        for j in i + 1..f.movers.len() {
            assert!(
                !aabbs_overlap(mover_swept(&f.movers[i]), mover_swept(&f.movers[j])),
                "pistons {i} and {j} can collide"
            );
        }
    }

    let lanes: Vec<&ZoneDef> = f.zones.iter().filter(|z| z.tag == "speed_lane").collect();
    assert_eq!(lanes.len(), 4, "one speed lane per cardinal data lane");
    for z in &lanes {
        assert_eq!(z.center[1], 4.0);
        assert_eq!(z.half[1], 4.0);
        assert_eq!(z.half[0].min(z.half[2]), 0.5, "a lane zone hugs the wall, not the floor");
        assert_eq!(z.half[0].max(z.half[2]), 14.0, "a lane zone spans the 28 m wall-run face");
        assert!((z.center[0].abs().max(z.center[2].abs()) - 27.0).abs() < 1e-4);
        assert!((z.center[0].abs().min(z.center[2].abs()) - 4.5).abs() < 1e-4);
        assert_eq!(z.tuning.len(), 4);
        assert_eq!(z.tuning["wall_run_m"], 10.0);
        assert_eq!(z.tuning["mult"], 1.15);
        assert_eq!(z.tuning["cap"], 1.6);
        assert_eq!(z.tuning["decay"], 0.9);
    }

    let core: Vec<&ZoneDef> = f.zones.iter().filter(|z| z.tag == "core_vent").collect();
    assert_eq!(core.len(), 1, "one core-vent trigger");
    let vent = core[0];
    assert_eq!(vent.center, [0.0, -3.5, 0.0]);
    assert_eq!(vent.half, [4.0, 2.5, 4.0], "8 m diameter, y -6..-1");
    assert_eq!(vent.tuning.len(), 3);
    assert_eq!(vent.tuning["fill_ticks"], 90.0);
    assert_eq!(vent.tuning["cooldown_ticks"], 1200.0);
    assert_eq!(vent.tuning["reveal_ticks"], 300.0);

    for z in &f.zones {
        let (lo, hi) = zone_aabb(z);
        for s in &l.level.spawns {
            assert!(!in_aabb(lo, hi, *s, 1.0), "zone {} reaches spawn {s:?}", z.tag);
        }
        for p in &l.pickups {
            assert!(!in_aabb(lo, hi, p.pos, 1.0), "zone {} reaches pickup {:?}", z.tag, p.pos);
        }
    }
}

#[test]
fn thirty_seconds_with_live_features_is_clean() {
    const TICKS: u32 = 30 * 60;
    let l = load();
    let mut s = Server::new(Cfg::default());
    l.level.apply_to_server(&mut s);
    s.set_level_features(l.features.clone());
    s.set_spawns(l.level.spawns.clone());
    for i in 0..3u16 {
        s.add_player(i + 1, l.level.spawns[i as usize]);
    }
    for t in 0..TICKS {
        let tick = s.tick;
        assert_eq!(tick, t);
        for id in 1..=3u16 {
            let p = s.players.iter().find(|p| p.id == id).unwrap();
            let pos = p.pos(&s.world);
            let want = (-pos[0]).atan2(-pos[2]);
            let step = angle_diff(want, dq_yaw(p.yaw)).clamp(-0.21, 0.21);
            let pkt = ClientPacket {
                ack_snapshot_tick: tick.saturating_sub(6).max(1),
                view: ViewState { from_tick: tick.saturating_sub(6).max(1), alpha: 0 },
                intents: vec![PlayerIntent {
                    tick,
                    move_z: 127,
                    aim_yaw: q_yaw(dq_yaw(p.yaw) + step),
                    aim_pitch: PITCH_LEVEL,
                    ..Default::default()
                }],
                ..Default::default()
            };
            s.ingest(id, &pkt.encode().unwrap());
        }
        s.frame(Duration::from_nanos(16_666_667));
        for p in &s.players {
            let pos = p.pos(&s.world);
            assert!(
                pos.iter().all(|c| c.is_finite()) && pos[0].abs() < 55.0 && pos[2].abs() < 55.0,
                "tick {t}: player {} at {pos:?}",
                p.id
            );
            assert_eq!(p.guard.strikes, 0, "tick {t}: player {} collected a strike", p.id);
        }
    }
    assert_eq!(s.tick, TICKS);
    assert_eq!(s.players.len(), 3, "nobody was kicked");
    for m in &l.features.movers {
        assert_eq!(m.pos_at(TICKS), m.pos_at(0), "a 30 s run is a whole number of 3 s cycles");
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let far = l
        .level
        .boxes
        .iter()
        .map(|b| b.center[0].abs() + b.half[0])
        .chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2]))
        .fold(0.0f32, f32::max);
    let top = l
        .level
        .boxes
        .iter()
        .map(|b| b.center[1] + b.half[1])
        .fold(0.0f32, f32::max);
    assert!(far <= HALF + 0.01, "geometry reaches {far} m");
    assert!(top <= 20.0, "tallest geometry {top} m");
    let q = shinobi_proto::quant::q_pos3([2.0 * far, top, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!(
        (back[0] - 2.0 * far).abs() < 0.01 && (back[1] - top).abs() < 0.01,
        "q_pos3 loses precision"
    );
    let _ = d2;
}
